"""Publish source-checked summaries; preserve LinkedIn dates separately from import dates."""
import json, pathlib
from bs4 import BeautifulSoup
R=pathlib.Path(__file__).resolve().parents[1]
def read(p): return json.loads((R/p).read_text(encoding='utf-8'))
def write(p,v): (R/p).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
site=read('content/site.json')
raw={x['id'].removeprefix('linkedin-'):x['data'] for x in read('source-archive/linkedin-structured.json')}
eu='https://eur-lex.europa.eu/eli/reg/2024/1860/oj/eng'
ec='https://health.ec.europa.eu/document/download/0f868301-8580-48e8-afa1-79aae839188e_en'
